func (r *queryResolver) QuizSessions(ctx context.Context, quizID string, state *model.QuizSessionState) ([]model.QuizSession, error) {
	ctx, span := otel.StartSpan(ctx, "quiz_session.list",
		attribute.String("quiz.id", quizID),
	)
	defer span.End()

	stateFilter := ""
	if state != nil {
		stateFilter = string(*state)
	}

	rows, err := r.DB.Queries.GetQuizSessionsByQuiz(ctx, sqlc.GetQuizSessionsByQuizParams{
		Quizid: quizID,
		State:  stateFilter,
	})
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to list quiz sessions: %w", err)
	}

	sessions := make([]model.QuizSession, len(rows))
	for i, row := range rows {
		sessions[i] = *convertQuizSessionToModel(row)
	}
	return sessions, nil
}

